"""
app.py — Balıkesir Üniversitesi Program Başarı Sırası Paneli
================================================================================

ÖNEMLİ: Bu sürüm Türkçe font ve logo için DIŞA BAĞIMLI DEĞİLDİR.
- Fontlar matplotlib paketinin içinden gelir (requirements.txt zaten matplotlib içerir).
- Logo, kodun içine base64 olarak GÖMÜLDÜ. Repo'da logo dosyası olmasa bile çalışır.

Çalıştırma: streamlit run app.py
"""

from __future__ import annotations

import io
import os
import base64
from pathlib import Path
from typing import List, Optional

import matplotlib
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import pandas as pd
import plotly.graph_objects as go
import streamlit as st
from PIL import Image, ImageDraw, ImageFont


# =============================================================================
# 1. DOSYA YOLLARI
# =============================================================================
BASE_DIR = Path(__file__).resolve().parent


def _find_file(filename: str, subdirs: tuple = ("", "assets", "data", "assets/fonts")) -> Optional[Path]:
    """Dosyayı birden fazla olası konumda ara, ilk bulduğunu döndür."""
    for sub in subdirs:
        candidate = BASE_DIR / sub / filename if sub else BASE_DIR / filename
        if candidate.exists():
            return candidate
    return None


EXCEL_PATH = _find_file("son_3_yil_program_basari_istatistigi.xlsx")


# =============================================================================
# 2. FONTLAR — MATPLOTLIB PAKETİNDEN (kesin garantili)
# =============================================================================
# matplotlib paketinin içinde DejaVu Sans hep gelir → Streamlit Cloud'da da var.
# Bu sayede ttf dosyalarını repo'ya pushlamak GEREKMEZ.
_MPL_FONTS_DIR = Path(matplotlib.get_data_path()) / "fonts" / "ttf"
FONT_REGULAR_PATH = _MPL_FONTS_DIR / "DejaVuSans.ttf"
FONT_BOLD_PATH = _MPL_FONTS_DIR / "DejaVuSans-Bold.ttf"

# Repo'daki ttf'leri opsiyonel olarak dene (override için)
_repo_regular = _find_file("DejaVuSans.ttf")
_repo_bold = _find_file("DejaVuSans-Bold.ttf")
if _repo_regular and _repo_regular.exists():
    FONT_REGULAR_PATH = _repo_regular
if _repo_bold and _repo_bold.exists():
    FONT_BOLD_PATH = _repo_bold


def load_font(size: int, bold: bool = False) -> ImageFont.FreeTypeFont:
    """Türkçe karakter destekli font yükle. matplotlib paketinden gelir,
    kesin garantili çalışır."""
    path = FONT_BOLD_PATH if bold else FONT_REGULAR_PATH
    try:
        return ImageFont.truetype(str(path), size)
    except (OSError, IOError):
        # Bu OLMAMALI — matplotlib zaten requirements'da
        return ImageFont.load_default()


# =============================================================================
# 3. LOGO — BASE64 GÖMÜLÜ (repo'da dosya gerekmez)
# =============================================================================
# Bu base64 stringi, baun_logo.png/jpg dosyasının içeriği.
# Repo'da `baun_logo.png` varsa onu kullanır; yoksa gömülü logo kullanılır.
_EMBEDDED_LOGO_B64 = """"""


def get_logo_image() -> Optional[Image.Image]:
    """Logo'yu RGBA PIL Image olarak döndür.
    1) Repo'da baun_logo.png varsa onu yükle
    2) Yoksa gömülü base64'ten yükle
    3) İkisi de yoksa None
    """
    # 1) Repo dosyası
    repo_logo = _find_file("baun_logo.png") or _find_file("baun_logo.jpg")
    if repo_logo and repo_logo.exists():
        try:
            return Image.open(repo_logo).convert("RGBA")
        except Exception:
            pass

    # 2) Gömülü base64
    try:
        if _EMBEDDED_LOGO_B64 and len(_EMBEDDED_LOGO_B64) > 100:
            data = base64.b64decode(_EMBEDDED_LOGO_B64)
            return Image.open(io.BytesIO(data)).convert("RGBA")
    except Exception:
        pass

    return None


def get_logo_base64_for_html() -> str:
    """Streamlit ekranında HTML'de göstermek için base64 döndür."""
    repo_logo = _find_file("baun_logo.png") or _find_file("baun_logo.jpg")
    if repo_logo and repo_logo.exists():
        with open(repo_logo, "rb") as f:
            return base64.b64encode(f.read()).decode("ascii")
    return _EMBEDDED_LOGO_B64 if _EMBEDDED_LOGO_B64 and len(_EMBEDDED_LOGO_B64) > 100 else ""


# =============================================================================
# 4. RENKLER
# =============================================================================
COLOR_LINE = "#1F3A6E"
COLOR_MARKER = "#2E5BA8"
COLOR_GRID = "#D6DCE5"
COLOR_BASELINE = "#6E7480"
COLOR_TEXT = "#0B1733"
COLOR_AXIS_LABEL = "#4A5568"
COLOR_BAUN_PRIMARY = "#008478"
COLOR_CARD_BG = "#F8FAFC"
COLOR_IMPROVE = "#065F46"
COLOR_DECLINE = "#92400E"
COLOR_NEUTRAL = "#4A5568"
COLOR_BG = "#FFFFFF"

YEAR_COLUMNS = ["2023", "2024", "2025"]


# =============================================================================
# 5. VERİ KATMANI
# =============================================================================
@st.cache_data(show_spinner=False)
def load_data() -> pd.DataFrame:
    if EXCEL_PATH is None or not EXCEL_PATH.exists():
        st.error(
            "🚨 **Veri dosyası bulunamadı!**\n\n"
            "`son_3_yil_program_basari_istatistigi.xlsx` dosyasının olması gereken yerler:\n"
            f"- `{BASE_DIR / 'son_3_yil_program_basari_istatistigi.xlsx'}`\n"
            f"- `{BASE_DIR / 'data' / 'son_3_yil_program_basari_istatistigi.xlsx'}`\n\n"
            "Excel dosyasını GitHub repo'ya pushladığından emin ol."
        )
        st.stop()

    df = pd.read_excel(EXCEL_PATH, sheet_name=0)
    df.columns = [str(c).strip() for c in df.columns]
    df["OKUL ADI"] = df["OKUL ADI"].ffill()
    df["PROGRAM ADI"] = (
        df["PROGRAM ADI"].astype(str).str.replace(r"\s+", " ", regex=True).str.strip()
    )
    for col in YEAR_COLUMNS:
        df[col] = pd.to_numeric(df[col], errors="coerce")
    df = df.dropna(subset=["PROGRAM ADI"])
    df = df[df["PROGRAM ADI"] != "nan"]
    return df.reset_index(drop=True)


# =============================================================================
# 6. YARDIMCI FONKSİYONLAR
# =============================================================================
def fmt_tr(v: Optional[float]) -> str:
    """1234567 → '1.234.567'."""
    if v is None or pd.isna(v):
        return "Veri yok"
    return f"{int(v):,}".replace(",", ".")


def wrap_text(text: str, font, max_width: int) -> List[str]:
    words = text.split()
    if not words:
        return [text]
    lines = []
    current = words[0]
    d = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    for word in words[1:]:
        test = current + " " + word
        bbox = d.textbbox((0, 0), test, font=font)
        if bbox[2] - bbox[0] <= max_width:
            current = test
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines


# =============================================================================
# 6.A BAŞLIK SARMA (2 satır - karakter sayısına göre)
# =============================================================================
def wrap_title_two_lines(title: str, max_chars_per_line: int = 28) -> str:
    """
    Uzun başlığı en fazla 2 satıra DENGELİ şekilde böler.
    - Kısa başlıklar (≤28 krk) tek satır.
    - Uzun başlıklarda: bölme noktası, ikinci satır 1. satırı geçmeyecek ŞEKİLDE
      seçilir → iki satır görsel olarak dengeli durur.
    - max_chars_per_line: her satırın YAKLAŞIK üst sınırı.
    """
    if not title:
        return title
    title = " ".join(title.split())  # fazla boşlukları toparla

    # Tek satıra sığıyorsa olduğu gibi
    if len(title) <= max_chars_per_line:
        return title

    words = title.split()
    if len(words) == 1:
        return title  # tek kelime ise bölemeyiz

    # DENGELİ bölme: ortaya en yakın boşluğu bul.
    # Önce her bölme noktasını dene, hedef: |len(line1) - len(line2)| minimum
    # AMA hiçbir satır max_chars_per_line'ı 3'ten fazla aşmasın.
    best = None  # (skor, line1, line2)
    for i in range(1, len(words)):
        l1 = " ".join(words[:i])
        l2 = " ".join(words[i:])
        # Her iki satır da tek başına makul uzunlukta olmalı
        if len(l1) > max_chars_per_line + 3 or len(l2) > max_chars_per_line + 3:
            continue
        score = abs(len(l1) - len(l2))
        if best is None or score < best[0]:
            best = (score, l1, l2)

    if best is None:
        # Hiçbir denge noktası bulunamadıysa (çok uzun başlık): ilk geçişte böl
        line1, line2 = "", ""
        for w in words:
            cand = (line1 + " " + w).strip()
            if len(cand) <= max_chars_per_line:
                line1 = cand
            else:
                line2 = (line2 + " " + w).strip()
        if not line1:
            line1 = words[0]
            line2 = " ".join(words[1:])
        return f"{line1}\n{line2}" if line2 else line1

    return f"{best[1]}\n{best[2]}"


# =============================================================================
# 6.B SABİT 6 YATAY ÇİZGİLİ Y EKSENİ HESAPLAMASI
# =============================================================================
def compute_fixed_y_ticks(values: List[Optional[float]], n_ticks: int = 6) -> tuple:
    """
    Veriye göre güzel-yuvarlak adımlı 6 tick döndürür (sabit sayıda).
    - Her grafik kendi aralığında çizilir (ki değişim görülebilsin)
    - AMA çizgi sayısı her grafikte SABİT (örn. 6)
    - Adım yuvarlak sayıya snap'lenir (1k, 2k, 5k, 10k, 20k, 50k, ...)
    Dönüş: (y_lo, y_hi, ticks_list)  -- y_lo > y_hi sıralama TERS değil; ters çevirme dış katmanda yapılır.
    """
    numeric = [v for v in values if v is not None and not pd.isna(v)]
    if not numeric:
        # Fallback - tipik bir aralık
        ticks = [0, 200000, 400000, 600000, 800000, 1000000]
        return ticks[0], ticks[-1], ticks

    v_min, v_max = min(numeric), max(numeric)
    if v_min == v_max:
        # Tek değer: ±%10'luk bant
        pad = max(v_max * 0.10, 1000)
        v_min, v_max = v_min - pad, v_max + pad

    raw_range = v_max - v_min
    # n_ticks-1 aralık olacak (6 çizgi = 5 aralık)
    raw_step = raw_range / (n_ticks - 1)

    # Yuvarlak step'e snap (1, 2, 5 × 10^k ailesi)
    import math
    magnitude = 10 ** math.floor(math.log10(raw_step))
    norm = raw_step / magnitude
    if norm < 1.5:
        nice = 1
    elif norm < 3:
        nice = 2
    elif norm < 7:
        nice = 5
    else:
        nice = 10
    step = nice * magnitude

    # Alt sınırı step'in katına yuvarla (aşağı), üst sınırı yukarı yuvarla
    y_lo = math.floor(v_min / step) * step
    y_hi = y_lo + step * (n_ticks - 1)

    # Veri y_hi'yi aşıyorsa step'i bir tık büyüt
    while y_hi < v_max:
        # Sıradaki nice step'e geç
        if nice == 1:
            nice = 2
        elif nice == 2:
            nice = 5
        elif nice == 5:
            nice = 10
        else:
            magnitude *= 10
            nice = 1
        step = nice * magnitude
        y_lo = math.floor(v_min / step) * step
        y_hi = y_lo + step * (n_ticks - 1)

    ticks = [y_lo + i * step for i in range(n_ticks)]
    return y_lo, y_hi, ticks


# =============================================================================
# 7. PLOTLY GRAFİK (Streamlit ekranı için)
# =============================================================================
def build_chart(years: List[str], values: List[Optional[float]], title: str, height: int = 500) -> go.Figure:
    numeric = [v for v in values if v is not None and not pd.isna(v)]
    fig = go.Figure()

    # Başlığı 2 satıra böl (Plotly için <br> kullan)
    wrapped_title = wrap_title_two_lines(title, max_chars_per_line=28).replace("\n", "<br>")
    title_has_two_lines = "<br>" in wrapped_title
    # 2 satır başlık varsa üst margin biraz daha
    top_margin = 95 if title_has_two_lines else 70

    if not numeric:
        fig.add_annotation(
            text="Bu program için veri yok",
            xref="paper", yref="paper", x=0.5, y=0.5,
            showarrow=False, font=dict(size=16, color=COLOR_AXIS_LABEL),
        )
        fig.update_layout(
            title=dict(text=f"<b>{wrapped_title}</b>", x=0.02, y=0.96,
                       font=dict(family="Inter, sans-serif", size=18, color=COLOR_TEXT)),
            height=height, margin=dict(l=80, r=50, t=top_margin, b=60),
            plot_bgcolor=COLOR_BG, paper_bgcolor=COLOR_BG, showlegend=False,
        )
        return fig

    # SABİT 6 yatay çizgi
    y_lo, y_hi, ticks = compute_fixed_y_ticks(values, n_ticks=6)

    labels = [fmt_tr(v) if v is not None and not pd.isna(v) else "" for v in values]

    fig.add_trace(go.Scatter(
        x=years, y=values,
        mode="lines+markers+text",
        line=dict(color=COLOR_LINE, width=3.5),
        marker=dict(size=18, color=COLOR_MARKER, line=dict(color="#FFFFFF", width=3)),
        text=labels,
        textposition="top center",
        textfont=dict(size=15, color=COLOR_TEXT, family="Inter, sans-serif"),
        hovertemplate="<b>%{x}</b><br>Başarı Sırası: %{text}<extra></extra>",
        connectgaps=False,
    ))

    fig.update_layout(
        title=dict(
            text=f"<b>{wrapped_title}</b>", x=0.02, y=0.96,
            font=dict(family="Inter, sans-serif", size=18, color=COLOR_TEXT),
        ),
        height=height,
        margin=dict(l=80, r=50, t=top_margin, b=60),
        plot_bgcolor=COLOR_BG, paper_bgcolor=COLOR_BG,
        showlegend=False,
        xaxis=dict(showgrid=False, zeroline=False, showline=False,
                   tickfont=dict(size=14, color=COLOR_AXIS_LABEL),
                   tickmode="array", tickvals=years, ticktext=years),
        # SABİT TICK MODU: 6 çizgi, ters çevrilmiş Y (yukarı = daha iyi sıra)
        yaxis=dict(showgrid=True, gridcolor=COLOR_GRID, griddash="dot",
                   zeroline=False, showline=False,
                   autorange=False,
                   range=[y_hi, y_lo],  # ters
                   tickmode="array",
                   tickvals=ticks,
                   ticktext=[fmt_tr(t) for t in ticks],
                   tickfont=dict(size=13, color=COLOR_AXIS_LABEL)),
    )
    return fig


def build_comparison_chart(df: pd.DataFrame, school: str, height: int = 700) -> go.Figure:
    sub = df[df["OKUL ADI"] == school].copy()
    palette = ["#1F3A6E", "#2E5BA8", "#0F766E", "#B45309", "#7C3AED", "#DB2777",
               "#0EA5E9", "#10B981", "#F59E0B", "#EF4444", "#6366F1", "#06B6D4",
               "#84CC16", "#F97316", "#A855F7", "#EC4899", "#3B82F6", "#14B8A6",
               "#D946EF", "#8B5CF6", "#22C55E", "#FB923C", "#E11D48", "#0891B2",
               "#65A30D", "#9333EA"]

    fig = go.Figure()
    for i, (_, row) in enumerate(sub.iterrows()):
        color = palette[i % len(palette)]
        values = [row[y] if pd.notna(row[y]) else None for y in YEAR_COLUMNS]
        fig.add_trace(go.Scatter(
            x=YEAR_COLUMNS, y=values, mode="lines+markers",
            name=row["PROGRAM ADI"],
            line=dict(color=color, width=2.5),
            marker=dict(size=10, color=color, line=dict(color="#FFFFFF", width=2)),
            hovertemplate=f"<b>{row['PROGRAM ADI']}</b><br>%{{x}}: %{{y:,.0f}}<extra></extra>",
            connectgaps=False,
        ))

    fig.update_layout(
        title=dict(text=f"<b>{school} — Tüm Programlar Karşılaştırma</b>",
                   x=0.02, y=0.96, font=dict(size=17, color=COLOR_TEXT)),
        height=height,
        margin=dict(l=80, r=30, t=70, b=160),
        plot_bgcolor=COLOR_BG, paper_bgcolor=COLOR_BG,
        legend=dict(orientation="h", yanchor="top", y=-0.18, xanchor="left", x=0,
                    font=dict(size=11, color=COLOR_TEXT)),
        xaxis=dict(showgrid=False, zeroline=False, showline=False,
                   tickfont=dict(size=13, color=COLOR_AXIS_LABEL)),
        yaxis=dict(showgrid=True, gridcolor=COLOR_GRID, griddash="dot",
                   zeroline=False, showline=False, autorange="reversed",
                   tickfont=dict(size=12, color=COLOR_AXIS_LABEL),
                   tickformat=",d", separatethousands=True),
    )
    return fig


# =============================================================================
# 8. PNG EXPORT (matplotlib + Pillow ile yüksek kaliteli çıktı)
# =============================================================================
def render_chart_png(years: List[str], values: List[Optional[float]],
                     title: str, width_px: int = 1200, height_px: int = 860,
                     dpi: int = 170) -> Image.Image:
    """Matplotlib ile grafiği Türkçe karakter destekli olarak çiz.
    - Başlık otomatik 2 satıra bölünür (sığmıyorsa).
    - Y ekseninde SABİT 6 yatay çizgi (yuvarlak step).
    """
    import matplotlib.font_manager as fm

    # matplotlib paketindeki DejaVu Sans'ı kullan
    try:
        fm.fontManager.addfont(str(FONT_REGULAR_PATH))
        fm.fontManager.addfont(str(FONT_BOLD_PATH))
        plt.rcParams["font.family"] = "DejaVu Sans"
    except Exception:
        pass

    fig, ax = plt.subplots(figsize=(width_px / dpi, height_px / dpi), dpi=dpi)
    fig.patch.set_facecolor(COLOR_BG)
    ax.set_facecolor(COLOR_BG)

    x = list(range(len(years)))
    y = [v if v is not None and not pd.isna(v) else None for v in values]

    # Çizgi (None'lar arası kopuk)
    last = None
    for i, v in enumerate(y):
        if v is None:
            last = None
            continue
        if last is not None:
            ax.plot([last[0], i], [last[1], v], color=COLOR_LINE, linewidth=2.5, zorder=2)
        last = (i, v)

    # İşaretler + üst etiketler
    for i, v in enumerate(y):
        if v is None:
            continue
        ax.scatter(i, v, s=280, color=COLOR_MARKER,
                   edgecolors=COLOR_BG, linewidths=3, zorder=3)
        ax.annotate(fmt_tr(v), (i, v), xytext=(0, 18), textcoords="offset points",
                    ha="center", va="bottom", fontsize=15, fontweight="bold",
                    color=COLOR_TEXT)

    ax.set_xticks(x)
    ax.set_xticklabels(years, fontsize=15, color=COLOR_AXIS_LABEL)
    ax.set_xlim(-0.5, len(years) - 0.5)

    # SABİT 6 yatay çizgi - veri varsa
    numeric = [v for v in y if v is not None]
    if numeric:
        y_lo, y_hi, ticks = compute_fixed_y_ticks(values, n_ticks=6)
        ax.set_ylim(y_hi, y_lo)  # ters (yukarı = daha iyi)
        ax.set_yticks(ticks)

    ax.yaxis.set_major_formatter(mticker.FuncFormatter(
        lambda v, p: f"{int(v):,}".replace(",", ".")))
    ax.tick_params(axis="y", labelsize=13, colors=COLOR_AXIS_LABEL)
    ax.grid(axis="y", linestyle=":", linewidth=1, color=COLOR_GRID, zorder=1)
    ax.set_axisbelow(True)
    for s in ["top", "right", "left"]:
        ax.spines[s].set_visible(False)
    ax.spines["bottom"].set_color(COLOR_BASELINE)
    ax.spines["bottom"].set_linewidth(2)

    # BAŞLIK - 2 satıra bölünmüş, uzunluğa göre fontu otomatik ayarla
    wrapped_title = wrap_title_two_lines(title, max_chars_per_line=28)
    title_lines_list = wrapped_title.split("\n")
    title_lines = len(title_lines_list)
    longest_line = max(len(l) for l in title_lines_list)

    # Font boyutu: en uzun satır 28'i aştıkça (kelime sığmadığı için aşmış olabilir)
    # küçülsün — böylece taşma garantili önlenir.
    if longest_line <= 28:
        title_fs = 19
    elif longest_line <= 33:
        title_fs = 17
    else:
        title_fs = 15

    title_pad = 22 if title_lines == 1 else 14
    ax.set_title(wrapped_title, fontsize=title_fs, fontweight="bold", color=COLOR_TEXT,
                 loc="left", pad=title_pad)

    plt.tight_layout()
    buf = io.BytesIO()
    plt.savefig(buf, format="png", facecolor=COLOR_BG, edgecolor="none", dpi=dpi)
    plt.close(fig)
    buf.seek(0)
    return Image.open(buf).convert("RGB")


def render_metric_panel_png(school: str, program: str,
                            values: List[Optional[float]],
                            width: int = 720, height: int = 860) -> Image.Image:
    """Sağ taraftaki metrik panel - OKUNAKLI BÜYÜK FONTLARLA"""
    img = Image.new("RGB", (width, height), COLOR_BG)
    d = ImageDraw.Draw(img)

    # OKUNAKLI BÜYÜK FONTLAR
    f_school = load_font(38, bold=True)
    f_program = load_font(30, bold=False)
    f_label = load_font(28, bold=True)
    f_value = load_font(44, bold=True)
    f_interp = load_font(30, bold=True)
    f_pct = load_font(26, bold=False)

    margin = 28
    cx = margin
    cw = width - 2 * margin
    y = 32

    # Okul adı (max 2 satır)
    for line in wrap_text(school, f_school, cw)[:2]:
        d.text((cx, y), line, fill=COLOR_TEXT, font=f_school)
        y += 50

    y += 10

    # Program adı (max 2 satır)
    for line in wrap_text(program, f_program, cw)[:2]:
        d.text((cx, y), line, fill=COLOR_AXIS_LABEL, font=f_program)
        y += 38

    y += 18
    d.line([(cx, y), (cx + cw, y)], fill="#E5E7EB", width=2)
    y += 28

    v23, v24, v25 = values

    # 3 yıl kartı
    for label, value in [("2023 Başarı Sırası", v23),
                         ("2024 Başarı Sırası", v24),
                         ("2025 Başarı Sırası", v25)]:
        ch = 120
        d.rectangle([(cx, y), (cx + cw, y + ch)], fill=COLOR_CARD_BG)
        d.rectangle([(cx, y), (cx + 8, y + ch)], fill=COLOR_LINE)
        d.text((cx + 30, y + 18), label, fill=COLOR_AXIS_LABEL, font=f_label)
        d.text((cx + 30, y + 58), fmt_tr(value), fill=COLOR_TEXT, font=f_value)
        y += ch + 16

    # Net değişim kartı
    if v23 is not None and v25 is not None and not pd.isna(v23) and not pd.isna(v25):
        change = v25 - v23
        pct = (change / v23) * 100
        if change < 0:
            interp_text = f"İYİLEŞME ({abs(int(change)):,} sıra)".replace(",", ".")
            interp_col = COLOR_IMPROVE
        elif change > 0:
            interp_text = f"GERİLEME (+{int(change):,} sıra)".replace(",", ".")
            interp_col = COLOR_DECLINE
        else:
            interp_text = "Değişim yok"
            interp_col = COLOR_NEUTRAL
        pct_text = f"(%{pct:+.1f})".replace(".", ",")
    else:
        interp_text = "2023 verisi yok"
        interp_col = COLOR_NEUTRAL
        pct_text = ""

    ch = 180
    d.rectangle([(cx, y), (cx + cw, y + ch)], fill=COLOR_CARD_BG)
    d.rectangle([(cx, y), (cx + 8, y + ch)], fill=interp_col)
    d.text((cx + 30, y + 18), "2023 → 2025 Net Değişim",
           fill=COLOR_AXIS_LABEL, font=f_label)

    iy = y + 62
    for line in wrap_text(interp_text, f_interp, cw - 60)[:2]:
        d.text((cx + 30, iy), line, fill=interp_col, font=f_interp)
        iy += 40
    if pct_text:
        d.text((cx + 30, y + ch - 42), pct_text, fill=COLOR_AXIS_LABEL, font=f_pct)

    return img


def export_program_png(school: str, program: str,
                       years: List[str], values: List[Optional[float]]) -> bytes:
    """Tüm bölüm tek PNG: logo + başlık + grafik + metrik panel."""
    chart = render_chart_png(years, values, f"Başarı Sırası — {program}")
    metric = render_metric_panel_png(school, program, values, height=chart.height)

    body_w = chart.width + metric.width
    brand_h = 220
    total_h = brand_h + chart.height + 40

    canvas = Image.new("RGB", (body_w, total_h), COLOR_BG)

    # LOGO (180px, dikey ortalı)
    text_x = 35
    logo_size = 180
    logo_img = get_logo_image()
    if logo_img is not None:
        try:
            logo = logo_img.copy()
            logo.thumbnail((logo_size, logo_size), Image.LANCZOS)
            # Beyaz arka plana yapıştır (alpha varsa)
            wbg = Image.new("RGB", logo.size, COLOR_BG)
            if logo.mode == "RGBA":
                wbg.paste(logo, mask=logo.split()[3])
            else:
                wbg.paste(logo)
            paste_y = (brand_h - logo.size[1]) // 2
            canvas.paste(wbg, (35, paste_y))
            text_x = 35 + logo.size[0] + 25
        except Exception:
            pass

    # KURUM ADI (56px, dikey ortalı, turkuaz)
    dc = ImageDraw.Draw(canvas)
    f_brand = load_font(56, bold=True)
    bbox = dc.textbbox((0, 0), "BALIKESİR ÜNİVERSİTESİ", font=f_brand)
    text_h = bbox[3] - bbox[1]
    text_y = (brand_h - text_h) // 2 - 6
    dc.text((text_x, text_y), "BALIKESİR ÜNİVERSİTESİ",
            fill=COLOR_BAUN_PRIMARY, font=f_brand)

    canvas.paste(chart, (0, brand_h))
    canvas.paste(metric, (chart.width, brand_h))

    out = io.BytesIO()
    canvas.save(out, format="PNG", optimize=True)
    out.seek(0)
    return out.getvalue()


