# 9. STREAMLIT UI BİLEŞENLERİ
# =============================================================================
def render_metric_panel(school: str, program: str, values: List[Optional[float]]) -> None:
    """Streamlit'te grafiğin sağındaki metrik kartları."""
    v23, v24, v25 = values

    # Okul adı (büyük, raptiyesiz)
    st.markdown(
        f'<div style="font-family:Inter,sans-serif; font-size:22px; font-weight:700;'
        f' color:#0B1733; line-height:1.2; margin-bottom:8px;">{school}</div>',
        unsafe_allow_html=True,
    )
    # Program adı
    st.markdown(
        f'<div style="font-family:Inter,sans-serif; font-size:15px; color:#4A5568;'
        f' margin-bottom:8px;">{program}</div>',
        unsafe_allow_html=True,
    )
    st.markdown(
        '<hr style="margin:8px 0; border:none; border-top:1px solid #E5E7EB;">',
        unsafe_allow_html=True,
    )

    # 3 yıl kartı
    for label, value in [("2023 Başarı Sırası", v23),
                         ("2024 Başarı Sırası", v24),
                         ("2025 Başarı Sırası", v25)]:
        display = fmt_tr(value)
        st.markdown(
            f"""<div style="background:#F8FAFC; border-left:4px solid #1F3A6E;
                            padding:12px 16px; border-radius:6px; margin-bottom:10px;">
                <div style="color:#4A5568; font-size:13px;">{label}</div>
                <div style="color:#0B1733; font-size:22px; font-weight:700;">{display}</div>
            </div>""",
            unsafe_allow_html=True,
        )

    # Net değişim
    if v23 is not None and v25 is not None:
        change = v25 - v23
        pct = (change / v23) * 100
        if change < 0:
            txt = f"✅ İYİLEŞME ({abs(int(change)):,} sıra)".replace(",", ".")
            col = "#065F46"
        elif change > 0:
            txt = f"⚠️ GERİLEME (+{int(change):,} sıra)".replace(",", ".")
            col = "#92400E"
        else:
            txt = "➖ Değişim yok"
            col = "#4A5568"
        pct_str = f"(%{pct:+.1f})".replace(".", ",")
    else:
        txt = "2023 verisi yok"
        col = "#4A5568"
        pct_str = ""

    st.markdown(
        f"""<div style="background:#F8FAFC; border-left:4px solid {col};
                        padding:12px 16px; border-radius:6px;">
            <div style="color:#4A5568; font-size:13px;">2023 → 2025 Net Değişim</div>
            <div style="color:{col}; font-size:16px; font-weight:700;">{txt}</div>
            <div style="color:#4A5568; font-size:12px; margin-top:4px;">{pct_str}</div>
        </div>""",
        unsafe_allow_html=True,
    )


@st.cache_data(show_spinner=False, max_entries=200)
def cached_png(school: str, program: str, years: tuple, values: tuple) -> bytes:
    return export_program_png(school, program, list(years), list(values))


def render_download_button(school: str, program: str,
                           values: List[Optional[float]], key: str) -> None:
    """Sunucu tarafı PNG export — %100 güvenilir."""
    png = cached_png(school, program, tuple(YEAR_COLUMNS), tuple(values))
    safe_name = (f"BAUN_{program[:40]}".replace(" ", "_")
                 .replace("/", "-").replace("(", "").replace(")", ""))
    st.download_button(
        label="📥 Bu Grafiği PNG Olarak İndir (Logo + Başlık + Metrikler)",
        data=png,
        file_name=f"{safe_name}.png",
        mime="image/png",
        key=key,
        type="primary",
    )


